local function VOID_RAN(n)
    local result = {}
    for i = 1,n do
    	result[i] = i
    end
    local index
    local temp
    for j = n,1,-1 do
    	index = ran:Int(1,j)
    	temp = result[index]
    	result[index] = result[j]
    	result[j] = temp
    end
    return result
end
local function VOID_HSV(H,S,V)
    local H=H%360
    local C = V*S
    local X= C*(1-abs((H/60)%2-1))
    local m = V-C
    local R,G,B
    if H<=60 then
        R,G,B = C,X,0
    elseif H<=120 then
        R,G,B = X,C,0
    elseif H<=180 then
        R,G,B = 0,C,X
    elseif H<=240 then
        R,G,B = 0,X,C
    elseif H<=300 then
        R,G,B = X,0,C
    elseif H<=360 then
        R,G,B = C,0,X
    else
        return
    end
    R,G,B = 255*(R+m),255*(G+m),255*(B+m)
    return R,G,B
end
local function VOID_ELLI(ra, rb, a1, a2, x, y)
    x, y = x or 0, y or 0
    local x0 = x + ra * cos(a1) * cos(a2) - rb * sin(a1) * sin(a2)
    local y0 = y + ra * cos(a1) * sin(a2) + rb * sin(a1) * cos(a2)
    return x0, y0
end
