_editor_class["void_bg"]=Class(_spellcard_background)
_editor_class["void_bg"].init=function(self)
    _spellcard_background.init(self)
    _spellcard_background.AddLayer(self,"image:void_bg_pole2",false,0,0,0,0,0,0,"",1,1,
        function(self)
            self.task={}
            self.r, self.g, self.b = 31,29,42
        end,
        function(self)
            task.Do(self)
            self.y = -55+15*sin(self.timer/3)
        end,
        function(self)
        end
    )
    _spellcard_background.AddLayer(self,"image:void_bg_sun",false,0,150,0,0,0,0,"",0.4,0.4,
        function(self)
            self.task={}
        end,
        function(self)
            task.Do(self)
        end,
        function(self)
        end
    )
    _spellcard_background.AddLayer(self,"img_void",false,0,0,0,0,0,0,"",1,1,
        function(self)
            self.task={}
            --[[ 纹理名称（注：LoadImage节点格式化后的图像资源名称存在同名纹理，可直接使用）]]
                self.tex = "image:void_bg_wind"
            
            --[[ 兼容 LuaSTG Sub 新版本]]
                -- LuaSTG Sub 在 0.18.11-beta 修改了 lstg.SetTextureSamplerState 的写法，不再支持老写法
                -- 说实话 lstg.SetTextureSamplerState 在 LuaSTG Ex Plus 后期版本才开始出现
                -- 当时还不是公开 API，且是实验性的 API，还没稳定下来，修的还是全局状态非常危险
                -- 被改掉真的是太好了，我直接开香槟，好似
                
                ---@param major number
                ---@param minor number
                ---@param patch number
                ---@return number
                local function make_version(major, minor, patch)
                    return (major * 1000 * 1000) + (minor * 1000) + (patch)
                end
                
                ---@return boolean
                local function is_LuaSTG_Sub()
                    if lstg.GetVersionName then
                        if string.find(lstg.GetVersionName(), "LuaSTG Sub") then
                            return true
                        end
                    end
                    return false
                end
                
                ---@return boolean
                local function is_API_lstg_SetTextureSamplerState_new_behavior()
                    if is_LuaSTG_Sub() then
                        local major, minor, patch = lstg.GetVersionNumber()
                        if make_version(major, minor, patch) >= make_version(0, 18, 11) then
                            return true
                        end
                    end
                    return false
                end
                
                if is_API_lstg_SetTextureSamplerState_new_behavior() then
                    self.is_API_lstg_SetTextureSamplerState_old_behavior = false
                    lstg.SetTextureSamplerState(self.tex, "linear+wrap")
                else
                    self.is_API_lstg_SetTextureSamplerState_old_behavior = true
                end
            
            --[[ 中心点坐标]]
                self.x = 0
                self.y = 150
            
            --[[ 图层角度与自旋速度]]
                self.angle = 90
                self.omega = 0
            
            --[[ 计时器初始值]]
                self.timer = 0
            
            --[[ 扩散速度（负数为缩回）]]
                self.speed = 0.6
            
            --[[ 渲染范围（radiusMax为上限，radiusMin为下限，请保证radiusMax大于等于radiusMin）]]
                self.radiusMin = 0
                self.radiusMax = 1800
            
            --[[ 每一层的厚度与图像数（即每一层是几次重复拼接出来的）]]
                self.radius = 512
                self.duplicate = 1
            
            --[[ 分割数（整体为n边形，越大性能消耗越高，但效果越好）]]
                self.n = 256
            
            --[[ 分割模式（1为纵向分割，2为水平分割）]]
                self.mode = 2
            
            --[[ 图层颜色]]
                self.color = Color(255, 255, 255, 255)
            
            --[[ 图层混合模式]]
                self.blend = ""
            
        end,
        function(self)
            task.Do(self)
            self.angle = self.angle + self.omega
        end,
        function(self)
            --[[ 兼容 LuaSTG Ex Plus 后期版本以及 LuaSTG Sub 老版本]]
                if self.is_API_lstg_SetTextureSamplerState_old_behavior then
                    SetTextureSamplerState("address", "wrap")
                end
            
            --[[ 主要渲染代码]]
                local w, h = GetTextureSize(self.tex)
                local a, ta = self.angle, 0
                local da = 360 / self.n
                if self.mode == 1 then
                    local tda = w * self.duplicate / self.n
                    local t = -self.radiusMin / self.radius * h + self.timer * self.speed
                    local tv = -(self.radiusMax - self.radiusMin) / self.radius * h
                    for _ = 1, self.n do
                        RenderTexture(self.tex, self.blend, { self.x + self.radiusMin * cos(a), self.y + self.radiusMin * sin(a), 0.5, ta, t, self.color },
                                { self.x + self.radiusMin * cos(a + da), self.y + self.radiusMin * sin(a + da), 0.5, ta + tda, t, self.color },
                                { self.x + self.radiusMax * cos(a + da), self.y + self.radiusMax * sin(a + da), 0.5, ta + tda, t + tv, self.color },
                                { self.x + self.radiusMax * cos(a), self.y + self.radiusMax * sin(a), 0.5, ta, t + tv, self.color })
                        a = a + da
                        ta = ta + tda
                    end
                else
                    local tda = -h * self.duplicate / self.n
                    local t = -self.radiusMin / self.radius * w + self.timer * self.speed
                    local tv = -(self.radiusMax - self.radiusMin) / self.radius * w
                    for _ = 1, self.n do
                        RenderTexture(self.tex, self.blend, { self.x + self.radiusMin * cos(a), self.y + self.radiusMin * sin(a), 0.5, t, ta, self.color },
                                { self.x + self.radiusMin * cos(a + da), self.y + self.radiusMin * sin(a + da), 0.5, t, ta + tda, self.color },
                                { self.x + self.radiusMax * cos(a + da), self.y + self.radiusMax * sin(a + da), 0.5, t + tv, ta + tda, self.color },
                                { self.x + self.radiusMax * cos(a), self.y + self.radiusMax * sin(a), 0.5, t + tv, ta, self.color })
                        a = a + da
                        ta = ta + tda
                    end
                end
            
            --[[ 兼容 LuaSTG Ex Plus 后期版本以及 LuaSTG Sub 老版本]]
                if self.is_API_lstg_SetTextureSamplerState_old_behavior then
                    SetTextureSamplerState("address", "clamp")
                end
            
        end
    )
    _spellcard_background.AddLayer(self,"image:void_bg_pole1",false,0,0,0,0,0,0,"",1,1,
        function(self)
            self.task={}
            self.r, self.g, self.b = 20, 12, 36
        end,
        function(self)
            task.Do(self)
            self.y = -50+10*sin(self.timer/4)
        end,
        function(self)
        end
    )
    _spellcard_background.AddLayer(self,"image:void_bg_pole1",false,0,0,180,0,0,0,"",1,1,
        function(self)
            self.task={}
            self.r, self.g, self.b = 20, 12, 36
        end,
        function(self)
            task.Do(self)
            self.y = 170+10*sin(self.timer/4)
        end,
        function(self)
        end
    )
    _spellcard_background.AddLayer(self,"image:void_bg_0",false,0,0,0,0,0,0,"",1,1,
        function(self)
            self.task={}
            self.r, self.g, self.b = 82, 55, 150
        end,
        function(self)
            task.Do(self)
        end,
        function(self)
        end
    )
end
